{
  "claims": [
    {
      "kind": "qualitative",
      "text": "Cleveland-Cliffs is a leading North America-based steel producer with a focus on value-added sheet products, particularly for the automotive industry.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000100-0055",
          "quote": "We are a leading North America-based steel producer with focus on value-added sheet products, particularly for the automotive industry."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The company is vertically integrated from iron ore mining, pellet production, direct reduced iron and ferrous scrap processing through primary steelmaking and downstream finishing, stamping, tooling and tubing.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000100-0055",
          "quote": "We are vertically integrated from the mining of iron ore, production of pellets and direct reduced iron"
        },
        {
          "chunk_id": "CLF-000076406526000100-0055",
          "quote": "through primary steelmaking and downstream finishing, stamping, tooling, and tubing"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The company offers a full suite of flat steel products and is a leading supplier to the automotive sector.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000115-0068",
          "quote": "We offer a full suite of flat steel products encompassing effectively all of our customers' needs. We are a leading supplier to the automotive sector"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Ferrous raw materials are primarily internally sourced from iron ore mines in Michigan and Minnesota, and the company sells into four broad market categories.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000025-0024",
          "quote": "Ferrous raw materials for the production of steel are primarily internally sourced from our iron ore mines in Michigan and Minnesota"
        },
        {
          "chunk_id": "CLF-000076406526000025-0024",
          "quote": "We primarily sell our products to customers in four broad market categories."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "A sustained, significant decline in market pricing is one of the indicators that can trigger long-lived asset impairment, and adverse changes in these factors could have a material impact on the consolidated statements of operations and financial position.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000115-0108",
          "quote": "a sustained, significant decline in market pricing"
        },
        {
          "chunk_id": "CLF-000076406526000115-0108",
          "quote": "could have a material impact on our consolidated statements of operations and statements of financial position"
        }
      ]
    },
    {
      "kind": "quantitative",
      "text": "Revenue was {{m:revenue:FY-2}} in {{p:FY-2}}, {{m:revenue:FY-1}} in {{p:FY-1}}, {{m:revenue:FY0}} in {{p:FY0}}, and {{m:revenue:LTM}} in {{p:LTM}}; EBITDA was {{m:ebitda:FY0}} in {{p:FY0}} and {{m:ebitda:LTM}} in {{p:LTM}}.",
      "citations": []
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Debt/EBITDA rose from {{m:debt_to_ebitda:FY-2}} in {{p:FY-2}} to {{m:debt_to_ebitda:LTM}} in {{p:LTM}}, and net leverage rose from {{m:net_leverage:FY-2}} to {{m:net_leverage:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "EBITDA/interest coverage fell from {{m:interest_coverage:FY-2}} in {{p:FY-2}} to {{m:interest_coverage:LTM}} in {{p:LTM}}, while FCF/debt fell from {{m:fcf_to_debt:FY-2}} to {{m:fcf_to_debt:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The deterioration in {{p:FY-1}} and {{p:FY0}} reflected lower gross margins from a decrease in selling prices for steel products.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000025-0215",
          "quote": "A $989 million decrease in net income after adjustments for non-cash items due to lower gross margins resulting from a decrease in selling prices for our steel products."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Steelmaking Adjusted EBITDA increased compared with the prior-year periods, primarily due to higher gross margin, supporting a partial rebound in LTM coverage metrics.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000115-0083",
          "quote": "increased by $468 million and $927 million, respectively, as compared to the prior-year periods, primarily due to the increased gross margin from our Steelmaking operations."
        }
      ]
    },
    {
      "kind": "quantitative",
      "text": "In {{p:LTM}}, cash from operations of {{m:cfo:LTM}} was below capital expenditures of {{m:capex:LTM}}, contributing to negative FCF/debt of {{m:fcf_to_debt:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The company expects total cash used for capital expenditures over the next 12 months to be approximately $900 million, primarily for sustaining capital spend.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000100-0087",
          "quote": "We anticipate total cash used for capital expenditures during the next 12 months to be approximately $900 million, which primarily consists of sustaining capital spend"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "In {{p:LTM}}, liquidity coverage was {{m:liquidity_coverage:LTM}}, compared with {{m:liquidity_coverage:FY0}} in {{p:FY0}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "In {{p:LTM}}, cash and cash equivalents were {{m:cash:LTM}} and cash from operations was {{m:cfo:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "In {{p:LTM}}, capital expenditure was {{m:capex:LTM}}, dividends paid were {{m:dividends:LTM}}, and short-term debt was {{m:short_term_debt:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "Management identified cash, cash from operations, ABL facility availability, and capital markets as primary liquidity sources and stated that they would be adequate for the next twelve months.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000115-0090",
          "quote": "Our primary sources of liquidity are Cash and cash equivalents, cash generated from our operations, availability under our ABL Facility and access to capital markets."
        },
        {
          "chunk_id": "CLF-000076406526000115-0090",
          "quote": "We believe our liquidity and access to capital markets will be adequate to fund our cash requirements for the next 12 months and for the foreseeable future."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "In {{p:LTM}}, cash plus ABL facility availability equated to $3.2 billion in liquidity.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000115-0090",
          "quote": "The combination of cash and availability under our ABL Facility equated to $3.2 billion in liquidity"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "At {{p:FY0}}, the ABL facility had a maximum borrowing base of $4.75 billion.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000025-0329",
          "quote": "the ABL Facility has a maximum borrowing base of $4.75 billion"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "As of {{p:FY0}}, the maturity schedule shows no debt due in the next twelve months ({{m:maturity_year_1:FY0}}) or in year two ({{m:maturity_year_2:FY0}}), with {{m:maturity_year_3:FY0}} maturing in year three.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "Debt due within 24 months was {{m:debt_due_24m:FY0}}, or {{m:share_due_24m:FY0}} of total debt, and near-term maturity cover was {{m:near_term_maturity_cover:FY0}} at {{p:FY0}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "As of {{p:FY0}}, amounts due in year four, year five, and after year five are {{m:maturity_year_4:FY0}}, {{m:maturity_year_5:FY0}}, and {{m:maturity_after_year_5:FY0}}, respectively.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "During 2025, the company used note issuance proceeds to extend debt maturities by redeeming all remaining 2027 senior notes and repaying borrowings on its ABL Facility.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000025-0218",
          "quote": "we used the proceeds from these transactions to extend debt maturities by redeeming all remaining 2027 senior notes and repay borrowings on our ABL Facility."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The ABL Facility matures in June 2028 and has a maximum borrowing base of $4.75 billion.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000025-0219",
          "quote": "Our ABL Facility, which matures in June 2028, has a maximum borrowing base of $4.75 billion."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "As of September 30, 2026, the company was in compliance with the ABL Facility liquidity requirements, and the springing financial covenant requiring a minimum fixed charge coverage ratio of 1.0 to 1.0 was not applicable.",
      "citations": [
        {
          "chunk_id": "CLF-000076406526000115-0091",
          "quote": "we were in compliance with the ABL Facility liquidity requirements and, therefore, the springing financial covenant requiring a minimum fixed charge coverage ratio of 1.0 to 1.0 was not applicable"
        }
      ]
    }
  ]
}

